import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-inscription',
  templateUrl: './inscription.component.html',
  styleUrls: ['./inscription.component.scss']
})
export class InscriptionComponent {
  inscriptionForm: FormGroup;
  isLoading = false;
  errorMessage = '';
  successMessage = '';
  step: 'form' | 'confirmation' = 'form';
  email = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.inscriptionForm = this.fb.group({
      nom: ['', Validators.required],
      prenom: ['', Validators.required],
      nomUtilisateur: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', Validators.required]
    });

    // ✅ Log pour vérifier que le composant est chargé
    console.log('✅ InscriptionComponent chargé');
  }

  onSubmit(): void {
    console.log('🔵 Bouton S\'inscrire cliqué');
    console.log('🔵 Formulaire valide ?', this.inscriptionForm.valid);
    console.log('🔵 Valeurs du formulaire:', this.inscriptionForm.value);

    if (this.inscriptionForm.valid) {
      if (this.inscriptionForm.value.password !== this.inscriptionForm.value.confirmPassword) {
        this.errorMessage = 'Les mots de passe ne correspondent pas';
        console.log('🔴 Erreur: mots de passe différents');
        return;
      }

      this.isLoading = true;
      this.errorMessage = '';
      this.successMessage = '';

      console.log('🟢 Envoi des données au backend...');

      this.authService.inscrire(this.inscriptionForm.value).subscribe({
        next: (response) => {
          console.log('🟢 Réponse du backend:', response);
          this.isLoading = false;
          if (response.success) {
            this.email = this.inscriptionForm.value.email;
            this.successMessage = response.message;
            this.step = 'confirmation';
            console.log('🟢 Compte créé, étape confirmation');
          } else {
            this.errorMessage = response.message || 'Erreur lors de l\'inscription';
            console.log('🔴 Erreur backend:', response.message);
          }
        },
        error: (error) => {
          this.isLoading = false;
          console.error('🔴 Erreur HTTP:', error);
          this.errorMessage = error.error?.message || 'Erreur lors de l\'inscription. Vérifie ta connexion.';
        }
      });
    } else {
      console.log('🔴 Formulaire invalide');
      this.errorMessage = 'Veuillez remplir tous les champs correctement.';
    }
  }

  goBackToForm(): void {
    this.step = 'form';
    this.errorMessage = '';
    this.successMessage = '';
  }

  confirmer(code: string): void {
    console.log('🔵 Confirmation avec code:', code);
    if (!code || code.length !== 6) {
      this.errorMessage = 'Le code doit contenir 6 chiffres';
      return;
    }
    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';
    this.authService.confirmerCompte(this.email, code).subscribe({
      next: (response) => {
        this.isLoading = false;
        console.log('🟢 Réponse confirmation:', response);
        if (response.success) {
          this.successMessage = response.message;
          setTimeout(() => this.router.navigate(['/login']), 3000);
        } else {
          this.errorMessage = response.message || 'Code incorrect';
        }
      },
      error: (error) => {
        this.isLoading = false;
        console.error('🔴 Erreur confirmation:', error);
        this.errorMessage = error.error?.message || 'Code incorrect ou expiré';
      }
    });
  }

  renvoyerCode(): void {
    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';
    this.authService.renvoyerCode(this.email).subscribe({
      next: (response) => {
        this.isLoading = false;
        console.log('🟢 Renvoi code:', response);
        if (response.success) {
          this.successMessage = response.message;
        } else {
          this.errorMessage = response.message || 'Erreur lors du renvoi du code';
        }
      },
      error: (error) => {
        this.isLoading = false;
        console.error('🔴 Erreur renvoi:', error);
        this.errorMessage = error.error?.message || 'Erreur lors du renvoi du code';
      }
    });
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }
}
<div class="inscription-container">
  <div class="inscription-card">
    <h2>📝 Inscription</h2>
    <p>{{ step === 'form' ? 'Créer un compte' : 'Confirmation du code' }}</p>

    <!-- Formulaire d'inscription -->
    <form *ngIf="step === 'form'" [formGroup]="inscriptionForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label>Nom *</label>
        <input type="text" formControlName="nom" class="form-control" placeholder="Votre nom">
      </div>
      <div class="form-group">
        <label>Prénom *</label>
        <input type="text" formControlName="prenom" class="form-control" placeholder="Votre prénom">
      </div>
      <div class="form-group">
        <label>Nom d\'utilisateur *</label>
        <input type="text" formControlName="nomUtilisateur" class="form-control" placeholder="Nom unique">
      </div>
      <div class="form-group">
        <label>Email *</label>
        <input type="email" formControlName="email" class="form-control" placeholder="email@exemple.com">
      </div>
      <div class="form-group">
        <label>Mot de passe * (6 caractères min)</label>
        <input type="password" formControlName="password" class="form-control" placeholder="Minimum 6 caractères">
      </div>
      <div class="form-group">
        <label>Confirmer le mot de passe *</label>
        <input type="password" formControlName="confirmPassword" class="form-control" placeholder="Répétez le mot de passe">
      </div>

      <button type="submit" class="btn btn-primary btn-block" [disabled]="inscriptionForm.invalid || isLoading">
        {{ isLoading ? '⏳ En cours...' : 'S\'inscrire' }}
      </button>

      <div *ngIf="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>
      <div *ngIf="successMessage" class="alert alert-success">{{ successMessage }}</div>

      <p class="login-link">
        Déjà un compte ? <span class="btn-link" (click)="goToLogin()">Se connecter</span>
      </p>
    </form>

    <!-- Étape de confirmation -->
    <div *ngIf="step === 'confirmation'">
      <div class="alert alert-info">
        Un code de confirmation a été envoyé à <strong>{{ email }}</strong>.<br>
        <small>Vérifie la console du backend pour le code.</small>
      </div>

      <div class="form-group">
        <label>Code de confirmation (6 chiffres)</label>
        <input type="text" #codeInput class="form-control" placeholder="Ex: 123456" maxlength="6" autofocus>
      </div>

      <button class="btn btn-primary" (click)="confirmer(codeInput.value)" [disabled]="isLoading">
        {{ isLoading ? '⏳ Vérification...' : 'Confirmer' }}
      </button>
      <button class="btn btn-secondary" (click)="renvoyerCode()" [disabled]="isLoading">
        Renvoyer le code
      </button>
      <button class="btn btn-outline-secondary" (click)="goBackToForm()" [disabled]="isLoading">
        ⬅ Modifier
      </button>

      <div *ngIf="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>
      <div *ngIf="successMessage" class="alert alert-success">{{ successMessage }}</div>
    </div>
  </div>
</div>
